<?php batasi_akses_role(['admin','petugas']);
$bulan=$_GET['bulan']??date('m'); $tahun=$_GET['tahun']??date('Y');
$q=mysqli_query($koneksi,"SELECT p.*, s.namasiswa, g.namaguru, u.namauser, GROUP_CONCAT(CONCAT(b.namabarang,' x',dp.jumlahkeluar) SEPARATOR ', ') as obat FROM penanganan p LEFT JOIN siswa s ON p.idsiswa=s.idsiswa LEFT JOIN guru g ON p.idguru=g.idguru LEFT JOIN user u ON p.iduser=u.iduser LEFT JOIN detailpenanganan dp ON p.idpenanganan=dp.idpenanganan LEFT JOIN barang b ON dp.idbarang=b.idbarang WHERE MONTH(p.tanggalpenanganan)='$bulan' AND YEAR(p.tanggalpenanganan)='$tahun' GROUP BY p.idpenanganan ORDER BY p.tanggalpenanganan DESC");
?>
<div class="content-header"><div class="container-fluid"><div class="row mb-2"><div class="col-sm-6"><h1 class="m-0 text-success font-weight-bold"><i class="fas fa-calendar-alt mr-1"></i> Laporan Bulanan</h1></div><div class="col-sm-6 text-right"><form method="GET" class="form-inline float-right"><input type="hidden" name="halaman" value="laporanbulanan"><select name="bulan" class="form-control form-control-sm mr-1"><?php for($b=1;$b<=12;$b++){ $bl=str_pad($b,2,'0',STR_PAD_LEFT); echo "<option value='$bl' ".($bulan==$bl?'selected':'').">".date('F',mktime(0,0,0,$b,1))."</option>"; } ?></select><select name="tahun" class="form-control form-control-sm mr-2"><?php for($t=date('Y');$t>=2023;$t--) echo "<option value='$t' ".($tahun==$t?'selected':'').">$t</option>"; ?></select><button class="btn btn-success btn-sm">Tampilkan</button> <a href="index.php?halaman=cetaklaporanbulanan&bulan=<?= $bulan ?>&tahun=<?= $tahun ?>" target="_blank" class="btn btn-danger btn-sm ml-1"><i class="fas fa-print"></i> Cetak</a></form></div></div></div></div>
<div class="content"><div class="container-fluid"><div class="card card-success card-outline shadow-sm"><div class="card-header bg-light">Bulan <?= date('F Y',mktime(0,0,0,$bulan,1,$tahun)) ?> - Total <b><?= mysqli_num_rows($q) ?></b> pasien</div><div class="card-body p-0 table-responsive"><table class="table table-bordered mb-0"><thead class="bg-light"><tr><th>No</th><th>Tanggal</th><th>Pasien</th><th>Keluhan</th><th>Status</th><th>Obat</th></tr></thead><tbody><?php $no=1; while($r=mysqli_fetch_assoc($q)): ?><tr><td><?= $no++ ?></td><td><?= date('d/m/Y',strtotime($r['tanggalpenanganan'])) ?></td><td><?= $r['namasiswa']?:$r['namaguru'] ?></td><td><?= htmlspecialchars($r['keluhan']) ?></td><td><span class="badge badge-<?= $r['statuspasien']=='sembuh'?'success':'warning' ?>"><?= $r['statuspasien'] ?></span></td><td><small><?= $r['obat']?:'-' ?></small></td></tr><?php endwhile; ?></tbody></table></div></div></div></div>